import React, { useState } from "react";
import { createDelivery } from "../api/deliveryApi";
import { useNavigate } from "react-router-dom";

export default function CreateDeliveryForm() {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    customerId: "",
    address: "",
    status: "Assigned",
  });

  const [assignedDriver, setAssignedDriver] = useState<{ id: string; name: string } | null>(null);
  const [error, setError] = useState("");

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>
  ) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    try {
      const res = await createDelivery({
        customerId: form.customerId,
        address: form.address,
        status: form.status,
      });

      setAssignedDriver(res.data.assignedDriver);
      setForm({
        customerId: "",
        address: "",
        status: "Assigned",
      });
    } catch (err) {
      console.error("❌ Failed to create delivery", err);
      setError("❌ Failed to create delivery");
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ padding: "30px", maxWidth: "400px", margin: "auto" }}>
      <h2 style={{ marginBottom: "20px", textAlign: "center" }}>Create Delivery</h2>

      <input
        type="text"
        name="customerId"
        placeholder="Customer ID"
        value={form.customerId}
        onChange={handleChange}
        required
        style={{ marginBottom: "10px", width: "100%", padding: "8px" }}
      />

      <input
        type="text"
        name="address"
        placeholder="Delivery Address"
        value={form.address}
        onChange={handleChange}
        required
        style={{ marginBottom: "10px", width: "100%", padding: "8px" }}
      />

      <select
        name="status"
        value={form.status}
        onChange={handleChange}
        style={{ marginBottom: "10px", width: "100%", padding: "8px" }}
      >
        <option value="Assigned">Assigned</option>
        <option value="Pending">Pending</option>
        <option value="In Transit">In Transit</option>
        <option value="Delivered">Delivered</option>
      </select>

      <div>
        <button type="submit" style={{ padding: "10px 20px" }}>Create Delivery</button>
        <button type="button" onClick={() => navigate("/")} style={{ padding: "10px 20px", marginLeft: "10px" }}>
          ← Back to Dashboard
        </button>
      </div>

      {assignedDriver && (
        <div style={{ marginTop: "15px", fontWeight: "bold", color: "#007bff" }}>
          ✅ Assigned Driver: <strong>{assignedDriver.name}</strong> (ID: {assignedDriver.id})
        </div>
      )}

      {error && <div style={{ marginTop: "15px", fontWeight: "bold", color: "red" }}>{error}</div>}
    </form>
  );
}
